import{_ as i,o as n,c as t,a3 as r}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"ATLAS File Studio","description":"","frontmatter":{},"headers":[],"relativePath":"projects/atlas-plugins/file-studio.md","filePath":"projects/atlas-plugins/file-studio.md","lastUpdated":1793023597000}'),a={name:"projects/atlas-plugins/file-studio.md"};function s(d,e,o,l,u,c){return n(),t("div",null,[...e[0]||(e[0]=[r(`<h1 id="atlas-file-studio" tabindex="-1">ATLAS File Studio <a class="header-anchor" href="#atlas-file-studio" aria-label="Permalink to &quot;ATLAS File Studio&quot;">​</a></h1><p>ATLAS File Studio ist das zweite unabhängige ATLAS-Plugin. Es soll Dateien in freigegebenen Home-Assistant-Pfaden bearbeiten, ohne standardmäßig freien Root-Zugriff zu erlauben.</p><h2 id="papierkorb-und-historie-uber-app-updates" tabindex="-1">Papierkorb und Historie über App-Updates <a class="header-anchor" href="#papierkorb-und-historie-uber-app-updates" aria-label="Permalink to &quot;Papierkorb und Historie über App-Updates&quot;">​</a></h2><p>Ab ATLAS <strong>0.1.312</strong> liegen die vom ATLAS-Backend verwalteten Ablagen standardmäßig unter <code>ATLAS_PLUGIN_DATA_ROOT/.file-studio/{trash,history}</code>. Docker muss die Plugin-Datenablage als Volume behalten; in der HA-App liegt sie unter <code>/data/atlas-plugins</code>. Vorhandene Linux-Installer-Pfade und die Overrides <code>ATLAS_FILE_STUDIO_TRASH_ROOT</code> / <code>ATLAS_FILE_STUDIO_HISTORY_ROOT</code> bleiben gültig. Bei eigenen Pfaden müssen auch diese dauerhaft eingebunden und gesichert werden.</p><p><strong>Erster Wechsel von einer älteren Container-Version:</strong> Zuerst die alten Papierkorb-/Historienordner und die persistenten Daten sichern. File-Studio- Schreibaktionen bis zum Update pausieren. Den eigenständig ausführbaren Helfer aus dem geprüften ATLAS-Release in den noch vorhandenen alten Container kopieren:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/atlas-file-studio-retention.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ALTER_CONTAINER:/tmp/atlas-file-studio-retention.mjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ALTER_CONTAINER</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/atlas-file-studio-retention.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --app-root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --plugin-root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /data/atlas-plugins</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Die Pfade gelten für das Standard-Image; bei eigenen Installationen prüfen. Bei der HA-App denselben Helfer im bisherigen App-Terminal vor dem Update ausführen. Er übernimmt erreichbare Altbestände einmalig, erhält Quellen und Eintragskennungen und überschreibt keine abweichenden Zieldateien. Konflikte zuerst anhand der Sicherung prüfen. Nach Erfolg auch die persistente Ablage sichern, dann den Container ersetzen. Ein Übernahmemarker verhindert, dass wiederhergestellte Einträge beim Neustart erneut importiert werden.</p><p>Bereits mit einem alten Container verlorene Dateien werden dadurch nicht zurückgeholt; dafür ist eine vorhandene Sicherung nötig. Nach der isolierten Prüfung wurde am 16.10.2026 auch der Wechsel von 0.1.311 auf 0.1.312 auf Proxmox und Pi 5 geprüft: vorher frische HA-Backups, Übernahme im alten Container und PC-Sicherung der alten sowie vorbereiteten Ablagen. Je Host bleiben beide alten Papierkorbeinträge und alle zwölf Historien-Dateien erhalten, ebenso Einstellungen, aktive Dateien, Projekte und Plugins. Dies ist kein Test einer vollständigen HAOS-Backup-Wiederherstellung.</p><p>Ein separater vollständiger HAOS-Restore wurde anschließend mit eigenen Testdaten geprüft: verschlüsseltes Vollbackup auf dem PC sichern, in eine frische Hyper-V- HAOS-Instanz hochladen und über den Supervisor wiederherstellen. Einstellungen, Projekt, sechs Plugins, Papierkorb und Historie sowie 154 geprüfte Dateien bleiben erhalten. Die Testadresse wurde beibehalten; Pi 5 und Proxmox bleiben unverändert. Ein zweiter frischer HAOS-Test wurde unter einer anderen IP-Adresse geprüft: Alle 154 Dateien und die bisherigen Zugangsdaten bleiben erhalten. Gespeicherte Adressen werden nicht automatisch umgeschrieben. Nach der Wiederherstellung in der <strong>Konfiguration der ATLAS-App</strong> nur die Home-Assistant-URL ändern und die App neu starten. Unter <strong>Einstellungen → Geräte &amp; Dienste → ATLAS Runtime → Konfigurieren</strong> die neue Runtime-Adresse einschließlich Port <code>4176</code> eintragen. Der bestehende HA-Token muss in diesem geprüften vollständigen Restore nicht ersetzt werden. Plugin-Links verwenden automatisch die neue ATLAS-Adresse. Anschließend Verbindung, Projekte, Papierkorb und Historie prüfen.</p><p>Diese isolierten Prüfungen ersetzen keinen Wiederherstellungstest eines produktiven Backups auf anderer Hardware; ARM64 und physische Geräte bleiben offen.</p><h2 id="repository" tabindex="-1">Repository <a class="header-anchor" href="#repository" aria-label="Permalink to &quot;Repository&quot;">​</a></h2><ul><li>GitHub: <code>https://github.com/rockbaer2007/atlas-file-studio-plugin</code></li><li>Installationsseite: <code>https://rockbaer2007.github.io/atlas-file-studio-plugin/install.html</code></li><li>Repository-Datei: <code>https://raw.githubusercontent.com/rockbaer2007/atlas-file-studio-plugin/main/repository.json</code></li></ul><h2 id="aktueller-stand" tabindex="-1">Aktueller Stand <a class="header-anchor" href="#aktueller-stand" aria-label="Permalink to &quot;Aktueller Stand&quot;">​</a></h2><p>File Studio ist als installierbares ATLAS-Plugin veröffentlicht und kann über das Demo-Repository in Administration und Hub getestet werden.</p><ul><li>aktueller Plugin-Stand: <code>0.1.52</code></li><li>französische Oberfläche: DE/EN/FR-Auswahl, Kopfzeile, zentrale Werkzeugleisten-Steuerelemente und Hinweise zur Upload-Grenze; Dialoge und weitere Ablaufmeldungen sind noch nicht vollständig übersetzt</li><li>Upload-Hinweis: Dateien bis 64 MiB können direkt hochgeladen werden; bei größeren Dateien verweist File Studio auf die Samba-App</li><li>dokumentierter Home-Assistant-App/Add-on-Stand: <code>0.1.312</code> (16.10.2026)</li><li>Bildvorschau: SVG-, PNG-, JPG/JPEG- und WebP-Dateien direkt an das separat installierte ATLAS Icon Studio übergeben. Rasterdateien öffnen sich dort als Vorschau; einfache SVG-Pfaddateien werden in das monochrome Iconset importiert.</li><li>Die Übergabe verwendet einen kurzlebigen Schlüssel im lokalen Browser und den freigegebenen File-Studio-Dateizugriff. Beide Plugins müssen auf demselben ATLAS-Server installiert sein; die Datei wird nicht hochgeladen oder dupliziert.</li><li>Dateibaum für den freigegebenen <code>/config</code>-Bereich</li><li>flexible Zwei-Spalten-Oberfläche mit begrenzbarer Maximalbreite und Maximalhöhe</li><li>kompakte Werkzeugzeile unterhalb von <code>Dateibaum /config</code>, damit die Icons in schmaleren Ansichten nicht in die rechte Dateiliste rutschen</li><li>Datei- und Ordneraktionen direkt am Pfad: Datei anlegen, Ordner anlegen, neu laden und alle Ordner einklappen</li><li>Editorfläche mit lokaler CodeMirror-6-Bündelung</li><li>große Dateien scrollen innerhalb der Editorfläche, damit die Statuszeile unten sichtbar bleibt</li><li>direkte Links öffnen Dateien auch dann, wenn sie tiefer liegen als der zuerst geladene Dateibaum, zum Beispiel Automation-Exporter-Ausgaben</li><li>Syntax Highlighting für YAML, JSON, JavaScript, TypeScript und Markdown</li><li>YAML-Prüfung vor dem Speichern mit Home-Assistant-Hinweisen für häufige Dateien wie <code>configuration.yaml</code>, <code>automations.yaml</code>, <code>scripts.yaml</code> und Packages, inklusive typischer Root-Keys, Automations-/Script-Struktur und direkt eingetragener Secret-Werte</li><li>Speichern der aktuell bearbeiteten Datei</li><li>automatische Backups vor dem Speichern, Verlaufsliste der letzten Sicherungen, Vergleich mit dem aktuellen Stand und Wiederherstellen einer ausgewählten Sicherung</li><li>lokal speichern, Drag-and-drop-Upload, Mehrfach-Upload und Download</li><li>Uploads werden im aktuell ausgewählten Ordner gespeichert</li><li>Nach dem Upload wird der Dateibaum aktualisiert, ohne die Datei automatisch zu öffnen</li><li>Downloadnamen werden im Browser automatisch hochgezählt, zum Beispiel <code>configuration.yaml</code>, <code>configuration-1.yaml</code>, <code>configuration-2.yaml</code></li><li>Upload-Konflikte können im File-Studio-Dialog ersetzt, umbenannt oder abgebrochen werden</li><li>Mehrfachauswahl für Löschen, Kopieren und Verschieben</li><li>Papierkorb mit Wiederherstellen statt sofortigem endgültigem Löschen; das rechte Toolbar-Icon ist grau im leeren Zustand und rot, sobald Einträge vorhanden sind</li><li>Favoritenleiste für häufig genutzte Dateien und Ordner</li><li>farbige Dateityp-Icons mit kompakten Typ-Badges</li><li>Suche mit Typfilter, optionaler Inhaltssuche, Trefferzeile und Inhaltsvorschau</li><li>opt-in Problembericht im File-Studio-Dialog mit Vorschau und vorbereitetem GitHub-Issue-Link; der Bericht enthält keine Home-Assistant-Token, Provider-API-Keys oder Dateiinhalte</li><li>Dateien bis 64 MiB direkt in einen freigegebenen Zielordner hochladen; der Transfer erfolgt als Binärdaten statt als Base64-JSON</li><li>bei größeren Dateien den Upload direkt abbrechen und auf die <a href="https://github.com/home-assistant/addons/tree/master/samba" target="_blank" rel="noreferrer">Home-Assistant-Samba-App</a> verweisen</li><li>ZIP-, TAR-, TAR.GZ- und TGZ-Inhaltsvorschau</li><li>einzelne Dateien direkt aus der Archivvorschau extrahieren, ohne das ganze Archiv zu entpacken</li><li>vollständige TAR-Archive mit Pfadprüfung sowie Grenzen für Dateigröße und Gesamtumfang entpacken</li><li><code>/config</code> als Standardwurzel</li><li>zusätzliche Pfad-Freigaben für <code>www</code>, <code>custom_components</code>, <code>addons</code> und <code>parent-of-config</code></li><li>kompakter Freigabehinweis in normaler, kleinerer Schrift; jeder freigegebene Pfad ist zur besseren Unterscheidung farblich markiert</li><li>Add-on-Verzeichnis nur nach Admin- oder Add-on-Freigabe</li><li>kein freier Root-Zugriff standardmäßig</li></ul><p>Die Editor-Bibliothek wird lokal mit dem Plugin ausgeliefert. Dadurch braucht File Studio für die Codeansicht kein CDN und bleibt auch im Home-Assistant-Add-on-Betrieb nachvollziehbar versioniert.</p><h2 id="sicherheitsmodell" tabindex="-1">Sicherheitsmodell <a class="header-anchor" href="#sicherheitsmodell" aria-label="Permalink to &quot;Sicherheitsmodell&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Versionskonsistenz ab 0.1.52</p><p>Katalog, Manifest, Paket und eingebettetes Manifest nennen einheitlich <strong>0.1.52</strong>. Der Paketgenerator synchronisiert nun auch den Katalog; eine lesende CI-Prüfung erkennt veraltete Artefakte vor der Veröffentlichung. Die frühere Abweichung Katalog 0.1.50 / Paket 0.1.51 ist behoben. Oberfläche und Datenformate bleiben unverändert. Update, Paket-Wiederherstellung, erneutes Update und Neustart sind isoliert mit erhaltenen Testeinstellungen, Dateien, Projekt, anderem Plugin, Papierkorb und Historie geprüft. Anschließend wurden am 16.10.2026 nach lokalen HA-Backups auch die nativen Abläufe geprüft: Proxmox <strong>0.1.50 → 0.1.52 → 0.1.50 → 0.1.52</strong>, Pi 5 <strong>0.1.51 → 0.1.52 → 0.1.51 → 0.1.52</strong>. Die sichere Wiederherstellung über die Administration und das erneute Repository-Update bestanden auf ATLAS 0.1.312 mit HA 2026.10.1. Vorhandene Dateien, Projekte, andere Plugins, Papierkorb und Historie blieben erhalten; Dateieditor und YAML-Basisprüfung funktionierten. Dabei war kein App-/HA-Neustart nötig. Das ist kein vollständiger HA-Restoretest.</p></div><p>Der erste Plugin-Vertrag beschreibt eine feste Zugriffspolitik:</p><table tabindex="0"><thead><tr><th>Pfad</th><th>Standard</th><th>Freigabe</th></tr></thead><tbody><tr><td><code>/config</code></td><td>aktiv</td><td>ohne zusätzliche Freigabe</td></tr><tr><td><code>/config/www</code></td><td>sichtbar als Fähigkeit</td><td>über Atlas Administration oder Add-on-Option</td></tr><tr><td><code>/config/custom_components</code></td><td>sichtbar als Fähigkeit</td><td>über Atlas Administration oder Add-on-Option</td></tr><tr><td><code>/addons</code></td><td>deaktiviert</td><td>über Atlas Administration oder Add-on-Option</td></tr><tr><td><code>parent-of-config</code></td><td>deaktiviert</td><td>nur bewusst als Admin-Freigabe</td></tr><tr><td><code>/</code></td><td>deaktiviert</td><td>nicht standardmäßig erlaubt</td></tr></tbody></table><p><code>/config</code> ist der normale Home-Assistant-Konfigurationsbereich. Dort liegen zum Beispiel <code>configuration.yaml</code>, <code>automations.yaml</code>, Dashboards, Themes, Blueprints, Skripte und lokale Webdateien unter <code>www</code>.</p><p><code>/addons</code> wird für lokale Home-Assistant-Add-ons genutzt. Dort können eigene Add-on-Ordner mit Dateien wie <code>config.yaml</code>, <code>Dockerfile</code>, Startskripten, Icons und Dokumentation liegen. Weil Änderungen dort direkt installierbare Add-ons beeinflussen können, bleibt dieser Bereich in File Studio standardmäßig gesperrt und wird nur nach bewusster Freigabe in der Atlas Administration sichtbar.</p><p>Im Home-Assistant-App/Add-on-Betrieb kommen diese Freigaben aus der Add-on-Konfiguration. In Docker- oder Linux-Installationen steuert Atlas Administration dieselben Datei-Fähigkeiten. Plugins erhalten dabei keine rohen Dauer-Secrets, sondern nur den freigegebenen Pfadkontext.</p><h2 id="home-assistant-update-hinweis" tabindex="-1">Home-Assistant-Update-Hinweis <a class="header-anchor" href="#home-assistant-update-hinweis" aria-label="Permalink to &quot;Home-Assistant-Update-Hinweis&quot;">​</a></h2><p>Nach jedem sichtbaren ATLAS-Update wird die Home-Assistant-App/Add-on-Version angehoben. Home Assistant vergleicht die installierte Version (<code>old</code>) mit der Repository-Version (<code>target</code>). Für diesen dokumentierten Stand lautet die App-Version <code>0.1.312</code>. Wenn weiter eine alte Zielversion erscheint, im App/Add-on-Store die Repository-Informationen neu laden und anschließend ATLAS aktualisieren oder neu starten. Die unabhängig veröffentlichte HACS-Integration bleibt bei <code>0.1.306</code>.</p><p>Plugin und ATLAS-App haben getrennte Versionen. Dokumentationsänderungen verändern keine Home-Assistant-Dateien.</p><h2 id="nachste-ausbaustufen" tabindex="-1">Nächste Ausbaustufen <a class="header-anchor" href="#nachste-ausbaustufen" aria-label="Permalink to &quot;Nächste Ausbaustufen&quot;">​</a></h2><ul><li>Home-Assistant-YAML-Hilfen weiter ausbauen, zum Beispiel mit echter Schema-/Service-Prüfung gegen eine verbundene Home-Assistant-Instanz</li><li>optionale RAR-Unterstützung einschließlich RAR5, falls ein frei nutzbares Backend verfügbar ist</li><li>Speichern von Icon-SVGs unter <code>/config/www/custom_local_icons/</code>, wenn die passende Home-Assistant-Integration genutzt wird</li><li>Umschaltung zwischen <code>/config</code> und dem Automation-Export-Ordner anzeigen, wenn der ATLAS Automation Exporter / Editor installiert ist</li></ul>`,28)])])}const g=i(a,[["render",s]]);export{p as __pageData,g as default};
